(() => {
  if (!firebase.apps.length) {
    throw new Error('Firebase no está inicializado');
  }

  const { db } = window;

  // Cuánto tiempo se le da a un turno "pendiente de pago" antes de dejar
  // de contar como ocupante del horario (Mercado Pago, ver
  // crearPreferenciaPago/notificarPagoMP en functions/index.js). Cubre el
  // caso de abandono real: el cliente cierra la pestaña de Mercado Pago
  // antes de pagar nada, así que nunca llega ningún webhook que libere el
  // turno — sin este filtro, ese horario quedaría bloqueado para siempre.
  // El rechazo/cancelación explícitos ya los libera el webhook al
  // instante, sin esperar este TTL. Debe coincidir con el vencimiento de
  // la preferencia de Mercado Pago (crearPreferenciaPago en
  // functions/index.js) — si este valor fuera mayor, el horario podría
  // quedar bloqueado sin necesidad una vez que Mercado Pago ya rechaza el
  // pago por vencido; si fuera menor, se corre el riesgo de liberar el
  // horario a otro cliente mientras el pago original todavía podría
  // completarse.
  const MINUTOS_TTL_PENDIENTE_PAGO = 10;

  function _esTurnoOcupante(turno) {
    if (turno.pagoSenia?.estado !== 'pendiente') return true; // sin pago online, o ya aprobado/rechazado -> cuenta normal
    const creadoEn = turno.createdAt?.toDate ? turno.createdAt.toDate() : null;
    if (!creadoEn) return true; // sin timestamp aún resuelto (escritura muy reciente) -> más seguro tratarlo como ocupante
    const minutosDesdeCreado = (Date.now() - creadoEn.getTime()) / 60000;
    return minutosDesdeCreado <= MINUTOS_TTL_PENDIENTE_PAGO;
  }

  window.firestoreDB = {
    // Obtener configuración (vive dentro del documento del negocio actual,
    // resuelto por subdominio — ver obtenerNegocioIdActual() en global.js)
    async obtenerConfiguracion() {
      const doc = await db.collection('negocios').doc(obtenerNegocioIdActual()).get();
      if (!doc.exists) throw new Error("No se encontró configuración");

      const data = doc.data();
      
      // Limpiar formatos de horarios
      if (typeof data.horarioApertura === 'string') {
        data.horarioApertura = data.horarioApertura.replace(/"/g, '');
      }
      if (typeof data.horarioCierre === 'string') {
        data.horarioCierre = data.horarioCierre.replace(/"/g, '');
      }
      
      // Normaliza diasLaborales a un array de números. El formulario de admin
      // guarda los checkboxes marcados como array de STRINGS (los `value` de
      // un <input> siempre son string) — eso no es un array "de un solo
      // elemento JSON" ni "ya todo números", así que se lo trataba como caso
      // no reconocido y cada lectura caía al default hardcodeado de lunes a
      // viernes. Bug real: por esto el negocio perdía el sábado apenas se
      // guardaba la configuración desde el panel, aunque hubiera especialistas
      // que sí trabajan ese día.
      const procesarDiasLaborales = (diasLaborales) => {
        if (!diasLaborales) return [1, 2, 3, 4, 5, 6]; // Valor por defecto (L-S)

        // Array de números o de strings numéricos (ej. checkboxes del admin)
        if (Array.isArray(diasLaborales)) {
          const numeros = diasLaborales.map(Number).filter(n => !isNaN(n));
          if (numeros.length > 0) return numeros;

          // Único elemento string que en realidad es JSON o CSV embebido
          if (diasLaborales.length === 1 && typeof diasLaborales[0] === 'string') {
            const str = diasLaborales[0].trim();
            try {
              if (str.startsWith('[') && str.endsWith(']')) {
                return JSON.parse(str).map(Number);
              }
              return str.split(',').map(Number).filter(n => !isNaN(n));
            } catch (e) {
              console.error("Error parseando diasLaborales:", e);
            }
          }

          return [1, 2, 3, 4, 5, 6]; // Valor por defecto
        }

        // Si es un string
        if (typeof diasLaborales === 'string') {
          // Si es un string JSON
          if (diasLaborales.startsWith('[') && diasLaborales.endsWith(']')) {
            try {
              return JSON.parse(diasLaborales).map(Number);
            } catch (e) {
              console.error("Error parseando diasLaborales JSON:", e);
            }
          }
          // Si es un string separado por comas
          return diasLaborales.split(',').map(Number).filter(n => !isNaN(n));
        }

        // Valor por defecto si no se puede procesar
        return [1, 2, 3, 4, 5, 6];
      };
      
      data.diasLaborales = procesarDiasLaborales(data.diasLaborales);
      
      // Convertir diasNoLaborables si es necesario
      if (typeof data.diasNoLaborables === 'string') {
        try {
          data.diasNoLaborables = JSON.parse(data.diasNoLaborables);
        } catch (e) {
          data.diasNoLaborables = data.diasNoLaborables.replace(/[\[\]\s]/g, '').split(',').filter(Boolean);
        }
      }
      
      return data;
    },

    // 1. Obtener configuración general. Se reconstruye la forma anidada
    // {empresa, reserva} que ya esperan los callers (cargarDatosGenerales en
    // app.js) aunque en Firestore ahora estos campos viven planos dentro del
    // propio documento del negocio, junto con horarios/servicios/etc.
    async obtenerConfigGeneral() {
        const doc = await db.collection('negocios').doc(obtenerNegocioIdActual()).get();
        if (!doc.exists) return {};
        const data = doc.data();
        return {
            empresa: {
                nombre: data.nombre,
                direccion: data.direccion,
                telefono: data.telefono,
                email: data.email,
                coordenadas: data.coordenadas,
                horariosAtencion: formatearHorariosAtencion(data),
                redes: data.redes,
                logoUrl: data.logoUrl
            },
            reserva: {
                señaMinima: data.señaMinima,
                tipoSenia: data.tipoSenia,
                maxDiasReserva: data.maxDiasReserva,
                anticipacionMinima: data.anticipacionMinima
            }
        };
    },

    // Obtener todas las categorías
    async obtenerCategorias() {
      const snapshot = await db.collection('categorias')
        .where('negocioId', '==', obtenerNegocioIdActual())
        .orderBy('orden')
        .get();
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
    },



    // 2. Obtener todos los servicios activos
    async obtenerServicios() {
        const snapshot = await db.collection('servicios')
            .where('negocioId', '==', obtenerNegocioIdActual())
            .where('activo', '==', true)
            .orderBy('orden')
            .get();
        return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
    },

    // 3. Obtener especialistas por categoría
    async obtenerEspecialistasPorCategoria(categoriaId) {
      const snapshot = await db.collection('especialistas')
        .where('negocioId', '==', obtenerNegocioIdActual())
        .where('categoriasId', 'array-contains', categoriaId)
        .where('activo', '==', true)
        .orderBy('orden')
        .get();
      return snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data(),
        categorias: doc.data().categoriasId // Puedes mapear esto a nombres si es necesario
      }));
    },


    // 5. Obtener turnos por ESPECIALISTA y fecha
    async obtenerTurnosPorEspecialistaYFecha(especialistaId, fecha) {
      try {
        const snapshot = await db.collection('turnos')
          .where('negocioId', '==', obtenerNegocioIdActual())
          .where('especialistaIds', 'array-contains', especialistaId)
          .where('fecha', '==', fecha)
          .get();
        
        return snapshot.docs.map(doc => {
          const data = doc.data();
          return {
            id: doc.id,
            ...data,
            // Asegurarse de que slotsPorEspecialista existe y tiene el formato correcto
            slotsPorEspecialista: data.slotsPorEspecialista || {}
          };
        }).filter(_esTurnoOcupante);
      } catch (error) {
        console.error("Error obteniendo turnos por especialista y fecha:", error);
        return [];
      }
    },

    async obtenerTurnosPorEspecialistasYFecha(especialistasIds, fecha) {
      const promises = especialistasIds.map(especialistaId =>
        this.obtenerTurnosPorEspecialistaYFecha(especialistaId, fecha)
      );
      const resultados = await Promise.all(promises);
      return resultados.flat();
    },

    async obtenerTurnosPorFecha(fecha) {
      const snapshot = await db.collection('turnos')
        .where('negocioId', '==', obtenerNegocioIdActual())
        .where('fecha', '==', fecha)
        .get();
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
    },

    // 6. Generar horarios por ESPECIALISTA y FECHA
    async generarHorariosDisponiblesEspecialista(especialistaId, fecha, duracionRequerida = 0) {
      try {
        const [config, especialistaDoc, turnosOcupados] = await Promise.all([
          this.obtenerConfiguracion(),
          db.collection('especialistas').doc(especialistaId).get(),
          this.obtenerTurnosPorEspecialistaYFecha(especialistaId, fecha)
        ]);

        if (!especialistaDoc.exists) {
          throw new Error('Especialista no encontrado');
        }

        const especialista = especialistaDoc.data();
        if (!especialista) throw new Error('Especialista no encontrado');

        // Determinar horario laboral del día
        const dias = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'];
        const diaSemana = obtenerDiaSemanaDeFechaStr(fecha);
        const diaKey = dias[diaSemana];
        const horarioDia = especialista.horarioLaboral?.[diaKey];

        // Si el especialista tiene horarioLaboral definido y ese día no está
        // activo, no trabaja — no caer al horario general del negocio. Y aun
        // si estuviera activo, el techo real son los días laborales del
        // NEGOCIO (dato que puede haber quedado desactualizado en algún
        // especialista puntual — ver roadmap).
        const diasLaborales = Array.isArray(config.diasLaborales) ? config.diasLaborales.map(Number) : [];
        const trabajaEseDia = (!especialista.horarioLaboral || horarioDia?.activo) && diasLaborales.includes(diaSemana);
        if (!trabajaEseDia) {
          return [];
        }

        // Usar horario del especialista o config general
        const horarioApertura = horarioDia?.activo ? horarioDia.inicio : config.horarioApertura;
        const horarioCierre = horarioDia?.activo ? horarioDia.fin : config.horarioCierre;

        // Calcular slots ocupados - PASA el especialistaId como parámetro
        const slotsOcupados = this._calcularSlotsOcupados(turnosOcupados, especialistaId);

        return this._generarHorarios(
            { ...config, horarioApertura, horarioCierre },
            slotsOcupados,
            fecha,
            duracionRequerida
        );
      } catch (error) {
        console.error("Error en generarHorariosDisponiblesEspecialista:", error);
        return [];
      }
    },

    // Modificar la función _generarHorarios para considerar la duración:
    _generarHorarios(config, slotsOcupados, fechaSeleccionada, duracionRequerida = 0) {
        const horarioApertura = config.horarioApertura;
        const horarioCierre = config.horarioCierre;
        
        // Asegurar formato correcto
        const horaApertura = parseInt(horarioApertura.replace('.', ':').split(':')[0]);
        const minApertura = parseInt(horarioApertura.replace('.', ':').split(':')[1] || 0);
        const horaCierre = parseInt(horarioCierre.replace('.', ':').split(':')[0]);
        const minCierre = parseInt(horarioCierre.replace('.', ':').split(':')[1] || 0);
        
        // Obtener duración con valor por defecto si es inválida
        let duracion = 30; // Valor por defecto
        if (config.duracionTurno && !isNaN(parseInt(config.duracionTurno))) {
            duracion = parseInt(config.duracionTurno);
        } else if (config.duracionTurnoBase && !isNaN(parseInt(config.duracionTurnoBase))) {
            duracion = parseInt(config.duracionTurnoBase);
        }
        
        // Validación de valores numéricos
        if (isNaN(horaApertura)) throw new Error('Horario apertura inválido');
        if (isNaN(minApertura)) minApertura = 0;
        if (isNaN(horaCierre)) throw new Error('Horario cierre inválido');
        if (isNaN(minCierre)) minCierre = 0;
        if (isNaN(duracion)) {
            console.warn('Duración turno inválida, usando valor por defecto de 30 minutos');
            duracion = 30;
        }

        const horarios = [];
        let horaActual = horaApertura;
        let minActual = minApertura;

        // Convertir horario de cierre a minutos para validación
        const cierreMinutos = horaCierre * 60 + minCierre;

        while (true) {
            const horarioStr = `${horaActual.toString().padStart(2, '0')}:${minActual.toString().padStart(2, '0')}`;
            
            // Verificar si este horario puede acomodar la duración requerida.
            // Si no se pidió una duración (0), igual hay que chequear el slot
            // base: de lo contrario el rango queda vacío y ningún turno
            // ocupado se detecta (todo se marca "disponible" sin excepción).
            const inicioMinutos = horaActual * 60 + minActual;
            const finMinutos = inicioMinutos + Math.max(duracionRequerida, duracion);
            
            // CORRECCIÓN: Verificar que el horario de fin no exceda el cierre
            const cabeEnJornada = finMinutos <= cierreMinutos;
            
            // Solo considerar horarios que estén dentro del rango laboral
            if (inicioMinutos >= cierreMinutos) break;
            
            // Verificar si todos los slots necesarios para la duración están disponibles
            let todosLosSlotsDisponibles = true;
            for (let min = inicioMinutos; min < finMinutos; min += 30) {
                const horaSlot = Math.floor(min / 60);
                const minutoSlot = min % 60;
                const horarioSlot = `${horaSlot.toString().padStart(2, '0')}:${minutoSlot.toString().padStart(2, '0')}`;
                
                if (slotsOcupados.includes(horarioSlot)) {
                    todosLosSlotsDisponibles = false;
                    break;
                }
            }
            
            const ocupado = !todosLosSlotsDisponibles;

            // Solo marcar como disponible si no está ocupado y cabe en la jornada
            horarios.push({
                hora: horarioStr,
                disponible: !ocupado && cabeEnJornada
            });

            // Avanzar el tiempo por la duración base, no la requerida
            minActual += duracion;
            if (minActual >= 60) {
                horaActual += Math.floor(minActual / 60);
                minActual = minActual % 60;
            }
            
            // Salir del loop si hemos superado el horario de cierre
            if (horaActual > horaCierre || (horaActual === horaCierre && minActual > minCierre)) {
                break;
            }
        }

        // Validación mínima de resultados
        if (horarios.length === 0) {
            console.error('No se generaron horarios con la configuración:', config);
            throw new Error('No se pudieron generar horarios');
        }

        return horarios;
    },


    // Arma, para cada especialista involucrado, sus límites de horario
    // laboral ese día (en minutos) y sus slots de 30' ya ocupados — una
    // sola lectura a Firestore por especialista, reutilizada para probar
    // todos los horarios candidatos del día sin repetir consultas.
    async _construirCachePorEspecialista(especialistaIds, fecha) {
      const config = await this.obtenerConfiguracion();
      const dias = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'];
      const diaSemana = obtenerDiaSemanaDeFechaStr(fecha);
      const diaKey = dias[diaSemana];

      // Techo obligatorio: los días laborales del NEGOCIO son el límite
      // real, sin importar lo que diga el horario propio de cada
      // especialista — ver el mismo chequeo en verificarDisponibilidadEspecialista (app.js).
      const diasLaborales = Array.isArray(config.diasLaborales) ? config.diasLaborales.map(Number) : [];
      if (!diasLaborales.includes(diaSemana)) {
        const cacheVacio = {};
        especialistaIds.forEach(id => { cacheVacio[id] = { trabajaEseDia: false }; });
        return cacheVacio;
      }

      const cache = {};
      await Promise.all(especialistaIds.map(async (especialistaId) => {
        const [especialistaDoc, turnosOcupados] = await Promise.all([
          db.collection('especialistas').doc(especialistaId).get(),
          this.obtenerTurnosPorEspecialistaYFecha(especialistaId, fecha)
        ]);

        if (!especialistaDoc.exists) {
          cache[especialistaId] = { trabajaEseDia: false };
          return;
        }

        const especialista = especialistaDoc.data();
        const horarioDia = especialista.horarioLaboral?.[diaKey];

        // Mismo criterio que verificarDisponibilidadEspecialista (app.js):
        // si el especialista tiene horarioLaboral definido y ese día no
        // está activo, no trabaja — no caer al horario general del negocio.
        if (especialista.horarioLaboral && !horarioDia?.activo) {
          cache[especialistaId] = { trabajaEseDia: false };
          return;
        }

        const apertura = horarioDia?.activo ? horarioDia.inicio : config.horarioApertura;
        const cierre = horarioDia?.activo ? horarioDia.fin : config.horarioCierre;

        const [ah, am] = apertura.replace('.', ':').split(':').map(Number);
        const [ch, cm] = cierre.replace('.', ':').split(':').map(Number);

        cache[especialistaId] = {
          trabajaEseDia: true,
          aperturaMin: ah * 60 + (am || 0),
          cierreMin: ch * 60 + (cm || 0),
          slotsOcupados: this._calcularSlotsOcupados(turnosOcupados, especialistaId)
        };
      }));

      return cache;
    },

    // Todas las permutaciones de un array (usado con pocos elementos — un
    // turno rara vez involucra más de 2 o 3 especialistas distintos).
    _permutarGrupos(grupos) {
      if (grupos.length <= 1) return [grupos];
      const resultado = [];
      for (let i = 0; i < grupos.length; i++) {
        const resto = [...grupos.slice(0, i), ...grupos.slice(i + 1)];
        for (const permutacion of this._permutarGrupos(resto)) {
          resultado.push([grupos[i], ...permutacion]);
        }
      }
      return resultado;
    },

    // Dado un horario de inicio candidato, busca alguna forma de ubicar
    // cada grupo (especialista + duración que le corresponde) en un bloque
    // contiguo de slots de 30', sin pisar turnos existentes de ESE
    // especialista ni salirse de su horario laboral. El orden entre grupos
    // es indiferente (lo determina quién esté realmente libre) — se prueba
    // cada combinación y se devuelve la primera que funcione, o null.
    _resolverAsignacionSecuencial(horarioInicio, grupos, cache) {
      const [horaStr, minStr] = horarioInicio.split(':').map(Number);
      const inicioBase = horaStr * 60 + minStr;

      for (const permutacion of this._permutarGrupos(grupos)) {
        let offset = 0;
        const asignacion = [];
        let valido = true;

        for (const grupo of permutacion) {
          const info = cache[grupo.especialistaId];
          const inicioGrupo = inicioBase + offset;
          const finGrupo = inicioGrupo + grupo.duracion;

          if (!info || !info.trabajaEseDia || inicioGrupo < info.aperturaMin || finGrupo > info.cierreMin) {
            valido = false;
            break;
          }

          let libre = true;
          for (let min = inicioGrupo; min < finGrupo; min += 30) {
            const horaSlot = Math.floor(min / 60);
            const minutoSlot = min % 60;
            const slot = `${horaSlot.toString().padStart(2, '0')}:${minutoSlot.toString().padStart(2, '0')}`;
            if (info.slotsOcupados.includes(slot)) {
              libre = false;
              break;
            }
          }

          if (!libre) {
            valido = false;
            break;
          }

          asignacion.push({ especialistaId: grupo.especialistaId, inicioMin: inicioGrupo, finMin: finGrupo });
          offset += grupo.duracion;
        }

        if (valido) return asignacion;
      }

      return null;
    },

    // Horarios de inicio donde el turno completo se puede ubicar: cada
    // especialista involucrado ocupa solo el sub-bloque de su(s) propio(s)
    // servicio(s), no la duración total — ver _resolverAsignacionSecuencial.
    // `gruposEspecialista` es un array [{especialistaId, duracion}], uno por
    // cada especialista distinto involucrado (duracion = suma de sus
    // servicios). Con un solo grupo, equivale al chequeo simple de siempre
    // (ese especialista libre para el bloque completo).
    async obtenerHorariosComunesDisponibles(fecha, gruposEspecialista) {
      try {
        if (!gruposEspecialista || gruposEspecialista.length === 0) return [];

        const especialistaIds = gruposEspecialista.map(g => g.especialistaId);
        const cache = await this._construirCachePorEspecialista(especialistaIds, fecha);

        if (especialistaIds.some(id => !cache[id]?.trabajaEseDia)) {
          return [];
        }

        const aperturaMin = Math.min(...especialistaIds.map(id => cache[id].aperturaMin));
        const cierreMin = Math.max(...especialistaIds.map(id => cache[id].cierreMin));

        const horariosDisponibles = [];
        for (let min = aperturaMin; min < cierreMin; min += 30) {
          const horarioStr = `${Math.floor(min / 60).toString().padStart(2, '0')}:${(min % 60).toString().padStart(2, '0')}`;
          if (this._resolverAsignacionSecuencial(horarioStr, gruposEspecialista, cache)) {
            horariosDisponibles.push(horarioStr);
          }
        }

        return horariosDisponibles;
      } catch (error) {
        console.error("Error obteniendo horarios comunes:", error);
        return [];
      }
    },


    // Verificar disponibilidad básica
    async verificarDisponibilidad(fecha, horario) {
          try {
            const snapshot = await db.collection('turnos')
                .where('negocioId', '==', obtenerNegocioIdActual())
                .where('fecha', '==', fecha)
                .where('horarioInicio', '==', horario)
                .limit(1)
                .get();
                
            return snapshot.empty;
        } catch (error) {
            console.error("Error verificando disponibilidad:", error);
            return false;
        }
    },



    async verificarBloqueosEspecialista(especialistaId, fecha) {
        try {
            // Convertir fecha a timestamp para comparación
            const fechaTimestamp = new Date(fecha).getTime();
            
            // Buscar bloqueos para este especialista
            const snapshot = await db.collection('bloqueos')
                .where('negocioId', '==', obtenerNegocioIdActual())
                .where('especialistaId', '==', especialistaId)
                .get();
                
            if (snapshot.empty) {
                return false;
            }
            
            // Verificar cada bloqueo
            for (const doc of snapshot.docs) {
                const bloqueo = doc.data();
                const inicioBloqueo = new Date(bloqueo.fechaInicio).getTime();
                const finBloqueo = new Date(bloqueo.fechaFin).getTime();
                
                // Si la fecha está dentro del rango de bloqueo
                if (fechaTimestamp >= inicioBloqueo && fechaTimestamp <= finBloqueo) {
                    return true;
                }
            }
            
            return false;
            
        } catch (error) {
            console.error("Error verificando bloqueos:", error);
            return false;
        }
    },
    
    // Verificar solapamientos
    async obtenerTurnosSolapados(fecha, horario, duracion) {
      const [horaStr, minutoStr] = horario.split(':');
      const horaInicio = parseInt(horaStr);
      const minutoInicio = parseInt(minutoStr);
      
      const minutoFin = minutoInicio + duracion;
      const horaFin = horaInicio + Math.floor(minutoFin / 60);
      const minutoFinAjustado = minutoFin % 60;
      const horarioFin = `${horaFin.toString().padStart(2, '0')}:${minutoFinAjustado.toString().padStart(2, '0')}`;
      
      const snapshot = await db.collection('turnos')
        .where('negocioId', '==', obtenerNegocioIdActual())
        .where('fecha', '==', fecha)
        .where('horarioInicio', '>=', horario)
        .where('horarioInicio', '<', horarioFin)
        .get();
        
      return snapshot.docs.map(doc => doc.data());
    },

    // Bloqueo temporal
    async bloquearTurnoTemporal(fecha, horario, userId) {
      const docRef = await db.collection('bloqueos_temporales').add({
        negocioId: obtenerNegocioIdActual(),
        fecha,
        horario,
        userId,
        timestamp: firebase.firestore.FieldValue.serverTimestamp(),
        expiresAt: new Date(Date.now() + 5*60*1000) // 5 minutos de expiración
      });
      return docRef.id; // Devolver el ID automático
    },

    async eliminarBloqueoTemporal(bloqueoId) {
      await db.collection('bloqueos_temporales').doc(bloqueoId).delete();
    },

    async obtenerTurnosPorUsuario(userId) {
      try {
        const hoy = new Date();
        hoy.setHours(0, 0, 0, 0);
        const fechaHoy = hoy.toISOString().split('T')[0];

        const snapshot = await db.collection('turnos')
          .where('userId', '==', userId)
          .where('fecha', '>=', fechaHoy)
          .orderBy('fecha')
          .orderBy('horarioInicio')
          .get();

        return snapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        })).filter(_esTurnoOcupante);
      } catch (error) {
        console.error("Error obteniendo turnos del usuario:", error);
        return [];
      }
    },

    // Cancelación de turno por el propio cliente (self-service).
    // Respeta la misma anticipación de 24hs que ya comunica la FAQ del sitio.
    // userId se recibe por compatibilidad de firma, pero quien cancela de
    // verdad lo determina la Cloud Function a partir de context.auth.uid —
    // el borrado y el email de cancelación (cliente + negocio) ahora pasan
    // siempre por cancelarTurno (functions/index.js), nunca por un
    // .delete() directo desde acá.
    async cancelarTurnoUsuario(turnoId, userId) {
      try {
        const resultado = await firebase.functions().httpsCallable('cancelarTurno')({ turnoId });
        return resultado.data;
      } catch (error) {
        console.error('Error cancelando turno:', error);
        return { success: false, mensaje: error.message || 'Error al cancelar el turno. Intenta nuevamente.' };
      }
    },

    // Guardar turno
    async guardarTurno(turnoData) {
      try {
        // Obtener información detallada de los servicios
        const serviciosSnapshot = await db.collection('servicios')
          .where(firebase.firestore.FieldPath.documentId(), 'in', turnoData.serviciosIds)
          .get();
        
        // Obtener servicios en el mismo orden que serviciosIds
        const serviciosOrdenados = [];
        for (const servicioId of turnoData.serviciosIds) {
          const servicioDoc = serviciosSnapshot.docs.find(doc => doc.id === servicioId);
          if (servicioDoc) {
            serviciosOrdenados.push(servicioDoc);
          }
        }

        // Obtener el mapeo de categoría a especialista desde los datos del turno
        const { especialistasPorCategoria } = turnoData;

        // Calcular duración total y agrupar servicios por especialista
        let duracionTotal = 0;
        const serviciosPorEspecialista = {};
        const duracionPorEspecialista = {};

        serviciosOrdenados.forEach(servicioDoc => {
          const servicio = servicioDoc.data();
          duracionTotal += servicio.duracion || 30;

          const especialistaId = especialistasPorCategoria[servicio.categoriaId];

          if (!especialistaId) {
            throw new Error(`No se encontró especialista para la categoría ${servicio.categoriaId}`);
          }

          if (!serviciosPorEspecialista[especialistaId]) {
            serviciosPorEspecialista[especialistaId] = [];
            duracionPorEspecialista[especialistaId] = 0;
          }

          serviciosPorEspecialista[especialistaId].push({
            id: servicioDoc.id,
            nombre: servicio.nombre,
            duracion: servicio.duracion || 30,
            categoriaId: servicio.categoriaId
          });
          duracionPorEspecialista[especialistaId] += servicio.duracion || 30;
        });

        // Misma asignación secuencial que ya se usó para OFRECER este
        // horario (ver obtenerHorariosComunesDisponibles): cada especialista
        // ocupa solo el sub-bloque que le corresponde, no la duración total.
        // Se recalcula acá (no se reutiliza lo que vino del cliente) para
        // que el guardado sea siempre consistente con las reglas reales,
        // incluso si algo cambió entre elegir el horario y confirmar.
        const especialistaIds = Object.keys(serviciosPorEspecialista);
        const gruposEspecialista = especialistaIds.map(especialistaId => ({
          especialistaId,
          duracion: duracionPorEspecialista[especialistaId]
        }));

        const cache = await this._construirCachePorEspecialista(especialistaIds, turnoData.fecha);
        const asignacion = this._resolverAsignacionSecuencial(turnoData.horarioInicio, gruposEspecialista, cache);

        if (!asignacion) {
          throw new Error('Ese horario ya no está disponible para los especialistas elegidos. Probá con otro horario.');
        }

        const slotsPorEspecialista = {};
        asignacion.forEach(({ especialistaId, inicioMin, finMin }) => {
          const slots = [];
          for (let min = inicioMin; min < finMin; min += 30) {
            const horaSlot = Math.floor(min / 60);
            const minutoSlot = min % 60;
            slots.push(`${horaSlot.toString().padStart(2, '0')}:${minutoSlot.toString().padStart(2, '0')}`);
          }
          slotsPorEspecialista[especialistaId] = slots;
        });

        const negocioId = obtenerNegocioIdActual();
        // Si el negocio no cobra seña online, no hay ningún paso de
        // aprobación pendiente — el turno queda confirmado apenas se
        // guarda. Si cobra, crearPreferenciaPago (Cloud Function) pisa
        // esto con 'pendiente_pago' de inmediato después — este valor es
        // solo la mejor estimación mientras tanto, nunca la autoridad real.
        const estadoInicial = turnoData.pagoOnlineActivo ? 'pendiente_pago' : 'confirmado';
        const datosFinales = {
          ...turnoData,
          negocioId,
          duracionTotal: duracionTotal,
          serviciosPorEspecialista: serviciosPorEspecialista,
          slotsPorEspecialista: slotsPorEspecialista,
          especialistaIds: especialistaIds,
          estado: estadoInicial,
          createdAt: firebase.firestore.FieldValue.serverTimestamp(),
          actualizadoEl: firebase.firestore.FieldValue.serverTimestamp()
        };
        delete datosFinales.pagoOnlineActivo; // era solo un hint para calcular estadoInicial, no se persiste

        // cliente/observaciones se guardan aparte, en una subcolección
        // privada (turnos/{id}/privado/datos) — no en el documento
        // principal. El documento principal necesita ser legible por
        // cualquier autenticado (calcular disponibilidad de cualquier
        // negocio no depende de quién reservó), así que dejar ahí el
        // nombre/teléfono/email real del cliente exponía esos datos a
        // cualquiera, de cualquier negocio (ver firestore.rules). La
        // subcolección tiene su propia regla, mucho más restrictiva.
        const datosPrivados = {
          cliente: datosFinales.cliente,
          observaciones: datosFinales.observaciones
        };
        delete datosFinales.cliente;
        delete datosFinales.observaciones;

        // Escritura atómica contra duplicados (doble-click, doble-tap en
        // pantallas táctiles, o incluso dos pestañas abiertas del mismo
        // usuario intentando guardar a la vez): el ID del documento se
        // deriva de negocioId+userId+fecha+horarioInicio, así que dos
        // intentos de guardar EXACTAMENTE el mismo turno apuntan siempre
        // al mismo ID. Dentro de una transacción, si dos escrituras
        // compiten por ese mismo ID, Firestore reintenta automáticamente
        // la que pierde la carrera — en su reintento ya ve el documento
        // que ganó y no lo pisa. Esto cubre casos que una simple lectura-
        // antes-de-escribir no puede (dos escrituras en verdadero
        // paralelo). No afecta ningún uso legítimo: un mismo usuario no
        // puede tener dos turnos en el mismo horario de todas formas (ver
        // verificarConflictoTurnoPropio en app.js).
        if (turnoData.userId) {
          const idTurno = `${negocioId}_${turnoData.userId}_${turnoData.fecha}_${turnoData.horarioInicio.replace(':', '')}`;
          const docRef = db.collection('turnos').doc(idTurno);
          const privadoRef = docRef.collection('privado').doc('datos');

          const resultado = await db.runTransaction(async (transaction) => {
            const doc = await transaction.get(docRef);
            if (doc.exists) {
              return { duplicado: true, data: doc.data() };
            }
            transaction.set(docRef, datosFinales);
            transaction.set(privadoRef, datosPrivados);
            return { duplicado: false };
          });

          if (resultado.duplicado) {
            // cliente/observaciones ya no vienen en resultado.data (viven
            // en la subcolección, y esta lectura no la pidió) — para este
            // caso (turno repetido, se reusa el existente) alcanza con
            // los datos que YA tenía quien llamó a esta función, son los
            // mismos de todos modos.
            console.warn('Turno duplicado detectado y evitado, se reutiliza el existente:', idTurno);
            return { id: idTurno, ...resultado.data, cliente: turnoData.cliente, observaciones: turnoData.observaciones };
          }

          console.log(`Turno guardado exitosamente. ID: ${idTurno}`);
          return { id: idTurno, ...turnoData };
        }

        // Sin usuario identificado (no ocurre en el flujo actual, que
        // exige login antes de reservar) — comportamiento anterior.
        const docRef = await db.collection('turnos').add(datosFinales);
        await docRef.collection('privado').doc('datos').set(datosPrivados);
        console.log(`Turno guardado exitosamente. ID: ${docRef.id}`);
        return { id: docRef.id, ...turnoData };
      } catch (error) {
        console.error("Error guardando turno:", error);
        throw error;
      }
    },

    // AGREGAR al final para compatibilidad temporal:
    async generarHorariosDisponibles(fecha) {
        console.warn('DEPRECATED: Usar generarHorariosDisponiblesEspecialista()');
        return this.generarHorariosDisponiblesEspecialista('especialista_default', fecha);
    },

    _calcularSlotsOcupados(turnos, especialistaId) {
      const slotsOcupados = [];
      
      turnos.forEach(turno => {
        // Verificar si este turno involucra al especialista
        if (turno.especialistaIds && turno.especialistaIds.includes(especialistaId)) {
          // Usar los slots específicos para este especialista
          if (turno.slotsPorEspecialista && turno.slotsPorEspecialista[especialistaId]) {
            slotsOcupados.push(...turno.slotsPorEspecialista[especialistaId]);
          } else {
            // Fallback para turnos antiguos - calcular slots basados en horarioInicio y duración
            const [hora, minuto] = turno.horarioInicio.split(':').map(Number);
            const inicioMinutos = hora * 60 + minuto;
            const finMinutos = inicioMinutos + (turno.duracionTotal || 30);
            
            for (let min = inicioMinutos; min < finMinutos; min += 30) {
              const horaSlot = Math.floor(min / 60);
              const minutoSlot = min % 60;
              const horarioSlot = `${horaSlot.toString().padStart(2, '0')}:${minutoSlot.toString().padStart(2, '0')}`;
              
              if (!slotsOcupados.includes(horarioSlot)) {
                slotsOcupados.push(horarioSlot);
              }
            }
          }
        }
      });
      
      return slotsOcupados;
    }
  };
})();